// gen.mjs reads gen.go's output on stdin and writes unicode_node.go: where
// Node's toUpperCase, toLowerCase, case folding of a regex with the i and u
// flags, and \p{..} property classes differ from Go's tables. See gen.go.
import { readFileSync } from 'node:fs';

const props = ['L', 'Nl', 'Nd', 'Zs', 'Cc', 'Z', 'C', 'Ll', 'P', 'Lu', 'Pc'];
const res = props.map(p => new RegExp(`^\\p{${p}}$`, 'u'));
const hex = s => {
  let o = '';
  for (let i = 0; i < s.length; i++) o += s.charCodeAt(i).toString(16).padStart(4, '0');
  return o;
};
const units = h => h.match(/.{4}/g).map(x => '0x' + x).join(', ');
const up = [], lo = [], caseless = new Set(), flips = props.map(() => []);
for (const line of readFileSync(0, 'utf8').trim().split('\n')) {
  const [rh, u, l, m, bits] = line.split(' ');
  const r = parseInt(rh, 16);
  const s = String.fromCodePoint(r);
  const ju = hex(s.toUpperCase()), jl = hex(s.toLowerCase());
  if (ju !== u) up.push(`0x${rh}: {${units(ju)}},`);
  if (jl !== l) lo.push(`0x${rh}: {${units(jl)}},`);
  if (rh !== m && !new RegExp(`^\\u{${m}}$`, 'iu').test(s)) {
    caseless.add(rh);
    caseless.add(m);
  }
  props.forEach((p, i) => {
    if (res[i].test(s) !== (bits[i] === '1')) {
      const f = flips[i], last = f[f.length - 1];
      if (last && last[1] === r - 1) last[1] = r;
      else f.push([r, r]);
    }
  });
}
const out = [];
out.push('// Code generated by testdata/unicode/gen.mjs from Node ' + process.versions.node +
  ' (Unicode ' + process.versions.unicode + '). DO NOT EDIT.');
out.push('', 'package minimatch', '');
out.push('// nodeVersion is the Node whose tables these are.');
out.push(`const nodeVersion = "${process.versions.node}, Unicode ${process.versions.unicode}"`, '');
out.push('// upperExceptions are the code points whose toUpperCase in Node is not Go\'s unicode.ToUpper, as UTF-16.');
out.push('var upperExceptions = map[rune][]uint16{', ...up, '}', '');
out.push('// lowerExceptions are the code points whose toLowerCase in Node is not Go\'s unicode.ToLower, as UTF-16.');
out.push('var lowerExceptions = map[rune][]uint16{', ...lo, '}', '');
out.push('// caseless are the code points Go folds with another and Node folds with none.');
out.push('var caseless = map[rune]bool{', ...[...caseless].map(h => `0x${h}: true,`), '}', '');
out.push('// propertyFlips are, for each property, the ranges of code points where Node and Go disagree.');
out.push('var propertyFlips = map[string][][2]rune{');
const h = n => '0x' + n.toString(16);
props.forEach((p, i) => { if (flips[i].length) out.push(`"${p}": {${flips[i].map(([a, b]) => `{${h(a)}, ${h(b)}}`).join(', ')}},`); });
out.push('}');
console.log(out.join('\n'));
